describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it.each([
      [0, 100, "zero upToGrams"],
      [-1, 100, "negative upToGrams"],
      [1.5, 100, "non-integer upToGrams"],
    ])("rejects bracket upToGrams=%d (%s)", (upTo, cost) => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: upTo, costCents: cost }]),
      ).toThrow(RangeError);
    });

    it.each([
      [100, -1, "negative costCents"],
      [100, 1.5, "non-integer costCents"],
    ])("rejects bracket costCents=%d (%s)", (upTo, cost) => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: upTo, costCents: cost }]),
      ).toThrow(RangeError);
    });

    it("rejects invalid overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            1.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for items with no weight", () => {
      expect(calc.computeShippingCents(mkLines(["a", 1]), 1000)).toBe(0);
    });

    it("selects the correct bracket for weight at lower boundary", () => {
      // 500g exactly → first bracket
      expect(calc.computeShippingCents(mkLines(["a", 1, 500]), 1000)).toBe(300);
    });

    it("selects next bracket when weight exceeds current", () => {
      // 501g → second bracket
      expect(calc.computeShippingCents(mkLines(["a", 1, 501]), 1000)).toBe(600);
    });

    it("selects highest bracket at boundary", () => {
      // 5000g → third bracket
      expect(calc.computeShippingCents(mkLines(["a", 1, 5000]), 1000)).toBe(1200);
    });

    it("uses heaviest bracket cost when no overflow set", () => {
      // 5001g → overflow, defaults to last bracket
      expect(calc.computeShippingCents(mkLines(["a", 1, 5001]), 1000)).toBe(1200);
    });

    it("uses overflowCostCents when set", () => {
      const withOverflow = new WeightBasedShippingCalculator(brackets, 2000);
      expect(
        withOverflow.computeShippingCents(mkLines(["a", 1, 5001]), 1000),
      ).toBe(2000);
    });

    it("sums weight across multiple lines", () => {
      // 2 * 300g = 600g → second bracket (500 < 600 <= 1000)
      expect(calc.computeShippingCents(mkLines(["a", 2, 300]), 1000)).toBe(600);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      // 400g → first bracket (500) → 300
      expect(unsorted.computeShippingCents(mkLines(["a", 1, 400]), 1000)).toBe(300);
    });
  });
});

