import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(new PercentageDiscountPolicy(0).computeDiscountCents(1000)).toBe(0);
      expect(new PercentageDiscountPolicy(100).computeDiscountCents(1000)).toBe(1000);
    });
  });

  describe("computeDiscountCents", () => {
    const policy = new PercentageDiscountPolicy(10);

    it.each([
      [1000, 100, "10% of 1000"],
      [999, 99, "floors to 99 (99.9)"],
      [1, 0, "floors to 0 (0.1)"],
      [0, 0, "zero subtotal"],
      [-500, 0, "negative subtotal"],
    ])("subtotal=%i → %i (%s)", (subtotal, expected) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("rounds down fractional cents", () => {
      const p = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0
      expect(p.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → 33
      expect(p.computeDiscountCents(101)).toBe(33);
    });

    it("handles very large subtotal", () => {
      const p = new PercentageDiscountPolicy(50);
      expect(p.computeDiscountCents(1_000_000_00)).toBe(500_000_00);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [10.5, "non-integer"],
    ])("rejects %d (%s)", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(new FixedAmountDiscountPolicy(0).computeDiscountCents(1000)).toBe(0);
    });
  });

  describe("computeDiscountCents", () => {
    const policy = new FixedAmountDiscountPolicy(500);

    it.each([
      [1000, 500, "discount less than subtotal"],
      [500, 500, "discount equals subtotal"],
      [300, 300, "clamped to subtotal when smaller"],
      [0, 0, "zero subtotal"],
      [-100, 0, "negative subtotal"],
    ])("subtotal=%i → %i (%s)", (subtotal, expected) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePol = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePol, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0, plus min(100, 1000) = 100 → 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("can exceed subtotal (Cart clamps later)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Both get subtotal=1000 → 600+600 = 1200 (exceeds 1000)
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // 10% of 1000 = 100, remaining = 900; fixed 200 from 900 = 200; total = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("ordering affects the chain result", () => {
      // FixedAmount first, then Percentage
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // fixed 200 from 1000, remaining = 800; 10% of 800 = 80; total = 280
      expect(composite.computeDiscountCents(1000)).toBe(280);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(1000), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // 1000 from 1000 remaining=0, 500 from 0 → 0; total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps each child to remaining", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // 800 from 1000 → remaining 200; min(800, 200) = 200; total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

