import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";
import { vi } from "vitest";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [1000, "US"],
    [0, "FR"],
    [-100, "DE"],
  ])("computeTaxCents(%i, %s) returns 0", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([
      [-0.01, "negative default rate"],
      [1.01, "default rate > 1"],
      [NaN, "NaN default rate"],
      [Infinity, "infinite default rate"],
    ])("rejects defaultRate=%d (%s)", (rate) => {
      expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
    });

    it("rejects invalid region rates", () => {
      expect(
        () => new RegionalTaxCalculator({ US: -0.1 }),
      ).toThrow(RangeError);
      expect(
        () => new RegionalTaxCalculator({ US: 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(() => new RegionalTaxCalculator({ US: 0 }, 0)).not.toThrow();
      expect(() => new RegionalTaxCalculator({ US: 1 }, 1)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses region-specific rate", () => {
      // 8.75% of 1000 = 87.5 → 87
      expect(calc.computeTaxCents(1000, "US-CA")).toBe(87);
    });

    it("uses default rate for unknown region", () => {
      // 5% of 1000 = 50
      expect(calc.computeTaxCents(1000, "JP")).toBe(50);
    });

    it("floors fractional cents", () => {
      // 20% of 999 = 199.8 → 199
      expect(calc.computeTaxCents(999, "FR")).toBe(199);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("works with default rate of 0", () => {
      const noDefault = new RegionalTaxCalculator({ US: 0.1 });
      expect(noDefault.computeTaxCents(1000, "XX")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax from the provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(1000, "US")).toBe(100);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("floors fractional cents", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 999 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US-CA")).toBe(87);
  });

  it("returns 0 for zero taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it.each([
    [-0.01, "negative rate"],
    [1.01, "rate over 1"],
    [NaN, "NaN rate"],
    [Infinity, "infinite rate"],
  ])("rejects invalid rate %d (%s) from provider", async (rate) => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(rate),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("network error");
  });
});

describe("totalLineWeightGrams", () => {
  const mkProduct = (id: string, weightGrams?: number): Product => ({
    id,
    name: id,
    unitPriceCents: 100,
    weightGrams,
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: mkProduct("a", 500), quantity: 2 },
      { product: mkProduct("b", 300), quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: mkProduct("a"), quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

