toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine, Product } from "../src/product.ts";

const mkProduct = (id: string, weightGrams?: number): Product => ({
  id,
  name: id,
  unitPriceCents: 1000,
  weightGrams,
});

const mkLines = (...specs: [string, number, number?][]): CartLine[] =>
  specs.map(([id, qty, weight]) => ({
    product: mkProduct(id, weight),
    quantity: qty,
  }));

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents(mkLines(["a", 1]), 1000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, undefined, "negative flatCents"],
      [5.5, undefined, "non-integer flatCents"],
    ])("rejects flatCents=%d (%s)", (flat, freeOver) => {
      expect(() => new FlatShippingCalculator(flat, freeOver)).toThrow(RangeError);
    });

    it.each([
      [500, -1, "negative freeOverCents"],
      [500, 10.5, "non-integer freeOverCents"],
    ])("rejects freeOverCents=%d (%s)", (flat, freeOver) => {
      expect(() => new FlatShippingCalculator(flat, freeOver)).toThrow(RangeError);
    });

    it("accepts 0 flatCents and 0 freeOverCents", () => {
      expect(() => new FlatShippingCalculator(0, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart below threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents(mkLines(["a", 1]), 4999)).toBe(500);
    });

    it("returns 0 when subtotal meets threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents(mkLines(["a", 1]), 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents(mkLines(["a", 1]), 6000)).toBe(0);
    });

    it("returns flat fee when no threshold configured", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents(mkLines(["a", 1]), 99999)).toBe(500);
    });

    it("returns 0 for empty cart regardless", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns flat fee when threshold is 0 but subtotal is 0", () => {
      // freeOverCents=0, subtotal=0 → 0 >= 0 → free
      const calc = new FlatShippingCalculator(500, 0);
      expect(calc.computeShippingCents(mkLines(["a", 1]), 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it.each([
      [0, 100, "zero upToGrams"],
      [-1, 100, "negative upToGrams"],
      [1.5, 100, "non-integer upToGrams"],
    ])("rejects bracket upToGrams=%d (%s)", (upTo, cost) => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: upTo, costCents: cost }]),
      ).toThrow(RangeError);
    });

    it.each([
      [100, -1, "negative costCents"],
      [100, 1.5, "non-integer costCents"],
    ])("rejects bracket costCents=%d (%s)", (upTo, cost) => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: upTo, costCents: cost }]),
      ).toThrow(RangeError);
    });

    it("rejects invalid overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            1.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for items with no weight", () => {
      expect(calc.computeShippingCents(mkLines(["a", 1]), 1000)).toBe(0);
    });

    it("selects the correct bracket for weight at lower boundary", () => {
      // 500g exactly → first bracket
      expect(calc.computeShippingCents(mkLines(["a", 1, 500]), 1000)).toBe(300);
    });

    it("selects next bracket when weight exceeds current", () => {
      // 501g → second bracket
      expect(calc.computeShippingCents(mkLines(["a", 1, 501]), 1000)).toBe(600);
