import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";

const mkProduct = (
  id: string,
  unitPriceCents = 1000,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(mkProduct("a"), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding same product twice", () => {
      const cart = new Cart();
      cart.add(mkProduct("a"), 2);
      cart.add(mkProduct("a"), 3);
      expect(cart.itemCount).toBe(5);
    });

    it.each([
      [0, "zero"],
      [-1, "negative"],
      [1.5, "non-integer"],
    ])("rejects quantity=%d (%s)", (qty) => {
      const cart = new Cart();
      expect(() => cart.add(mkProduct("a"), qty)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(mkProduct("a"), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown productId", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(mkProduct("a"), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(mkProduct("a"), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nope", 1)).toThrow(
        "Product nope is not in the cart",
      );
    });

    it.each([
      [-1, "negative"],
      [1.5, "non-integer"],
    ])("rejects invalid quantity=%d (%s)", (qty) => {
      const cart = new Cart();
      cart.add(mkProduct("a"), 1);
      expect(() => cart.updateQuantity("a", qty)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(mkProduct("a"), 1);
      cart.add(mkProduct("b"), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of the lines", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 500), 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.unitPriceCents).toBe(500);
      expect(snap[0]!.quantity).toBe(2);

      // mutating snapshot should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes correct totals with all defaults (no discount, no tax, free shipping)", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(2000);
    });

    it("returns zero totals for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.totalCents).toBe(0);
    });

    it("applies discount → tax on discounted subtotal → shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(mkProduct("a", 1000), 2);
      const t = cart.totals();

      // subtotal = 2000, discount = 200 (clamped), discounted = 1800
      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(200);

      // tax computed on discounted subtotal
      expect(tax.computeTaxCents).toHaveBeenCalledWith(1800, "US-CA");
      expect(t.taxCents).toBe(80);

      // shipping gets the lines and discounted subtotal
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        1800,
      );
      expect(t.shippingCents).toBe(500);

      // total = discounted + tax + shipping = 1800 + 80 + 500
      expect(t.totalCents).toBe(2380);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(mkProduct("a", 1000), 2);
      const t = cart.totals();
      // discount 5000 clamped to 2000
      expect(t.discountCents).toBe(2000);
      expect(t.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
      expect(t.totalCents).toBe(1000);
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(mkProduct("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(mkProduct("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("defaults region to US", () => {
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(mkProduct("a", 100), 1);
      cart.totals();
      expect(tax.computeTaxCents).toHaveBeenCalledWith(100, "US");
    });
  });

  describe("checkout", () => {
    let cart: Cart;

    beforeEach(() => {
      cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("b", 500), 1);
    });

    it("returns totals and lines without collaborators", async () => {
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2500);
      expect(result.lines).toHaveLength(2);
    });

    it("refreshes prices via priceFetcher", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1100)
          .mockResolvedValueOnce(600),
      };
      const result = await cart.checkout({ priceFetcher });
      // New subtotal: 1100*2 + 600*1 = 2800
      expect(result.totals.subtotalCents).toBe(2800);
    });

    it("throws InventoryError when item is not available", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.message).toBe("sold out");
        expect(invErr.requested).toBe(2);
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.available).toBe(1);
        expect(invErr.requested).toBe(2);
      }
    });

    it("passes when inventory is fully available", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2500);
    });

    it("uses asyncTaxProvider for tax calculation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({ region: "US" });
      cart.add(mkProduct("a", 1000), 1);

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 1000, no discount, tax = 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      expect(result.totals.totalCents).toBe(1100);
    });

    it("composes discount + async tax + shipping in checkout", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 300,
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
        region: "US",
      });
      cart.add(mkProduct("x", 2000), 1);

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal = 2000, discount = 500, discounted = 1500
      // tax = 10% of 1500 = 150, shipping = 300
      // total = 1500 + 150 + 300 = 1950
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(150);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(1950);
    });

    it("propagates priceFetcher rejection", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch fail")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch fail");
    });

    it("propagates inventoryChecker rejection", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockRejectedValue(new Error("service down")),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        "service down",
      );
    });

    it("propagates asyncTaxProvider failure", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const c = new Cart();
      c.add(mkProduct("a", 100), 1);
      await expect(c.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("generates default InventoryError message when reason is missing", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
        }),
      };
      const c = new Cart();
      c.add(mkProduct("z", 100), 3);
      try {
        await c.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.message).toContain("insufficient stock");
        expect(invErr.productId).toBe("z");
      }
    });
  });
});

